		/// messagetype. If invalid parameters are given (i.e. <c>null</c> references) this method simply returns
		/// </summary>
		/// <param name="output">The messagereceiver to be de-registered</param>
		/// <param name="className">The type of messages the messagereceiver should be deregistered from</param>
		public void deRegister(MessageReceiver output, string className) {

			// check parameters
			if (output == null)
				return; // invalid params
			if (className == null)
				return; // invalid params

			// get the type
			Type messageType = null;

			//try
