		/// <summary>
		/// Checks if the current messagetype is switched on to be distributed. If not, no messages of the given
		/// type are distributed or the given type of message is not registered here.
		/// </summary>
		/// <returns>
		/// Is <c>true</c> if the type of message is distributed <c>false</c> if not or messagetype is not
		/// registered here
		/// </returns>
		public bool isOn(Type messageType) {

			if (messageType == null)
				return false;

			MLink tmp = linkOf(messageType);

			if (tmp == null)
				return false; // type not registered here

			if (tmp.isOn) {
				return true;
			} else
				return false;

		}

		/// <summary>Checks if the given messagetype is registered at this messagedistributor.</summary>
		/// <returns>Is <c>true</c> if the messagetype is registered, <c>false</c> if not</returns>
		public bool isRegistered(Type messageType) {

			if (messageType == null)
				return false;

			MLink tmp = linkOf(messageType);

			if (tmp == null)
				return false; // type not registered here
			else
				return true;

		}

		/// <summary>
		/// Returns the messagelink for the given class or <c>null</c> if the class is not already registered.
		/// </summary>
		/// <param name="messageType">The class that the link is needed for</param>
		/// <returns>
		/// The messagelink for the given class or <c>null</c> if the given class is not registered yet
		/// </returns>
		private MLink linkOf(Type messageType) {

			if (_head == null)
				return null;
			else {

				for (MLink tmp = _head; tmp != null; tmp = tmp.next) {
					if (tmp.msgType == messageType)
						return tmp;
				}

			}

			return null;

		}

		/// <summary>
		/// Receives a message and forwards it to all messagereceiver objects registered with the type of message
		/// sent. Messages are sent, if the type of message is switched on and if the skipCounter is zero, thus not
		/// skipping any messages of that type.
		/// </summary>
		/// <param name="m">The message to be forwarded to all registered MessageReceivers</param>
		public void receive(Message m) {

			if (m == null)
				return; // again nulls

			MLink tmp = linkOf(m.GetType()); // get link in list of msgTypes

			if (tmp == null)
				return; // is null if type not registered here, so return???

			// checks if the message has to be skipped
			if (tmp.skipCount > 0)
			{
				tmp.skipCount--;
				return;
			}

			// check if messages of this type should be distributed to their
			// message receivers
			if (!tmp.isOn)
				return;

			// loop + send to all receivers
			for (int i = 0; i < tmp.clients.Count; i++)
			{
				tmp.clients[i].receive(m);
			}

		}

		/// <summary>
		/// Receives a reporter and forwards it to all messagereceiver objects registered with the type of reporter
		/// sent.
		/// </summary>
		/// <param name="r">The reporter to be forwarded to all registered messagereceivers.</param>
		public void receive(Reporter r) {

			if (r == null)
				return; // again nulls

			MLink tmp = linkOf(reporters); // get link in list of msgTypes

			if (tmp == null)
				return; // is null if type not registered here, so return???

			for (int i = 0; i < tmp.clients.Count; i++)
			{ // loop and
				tmp.clients[i].receive(r);
			}

		}

		/// <summary>Registers a messagereceiver object to receive messages of the given type.</summary>
		/// <param name="output">The messagereceiver to be registered</param>
		/// <param name="messageType">The type of messages the messagereceiver is registered with</param>
		public void register(MessageReceiver output, Type messageType) {

			// check parameters
			if (output == null)
				return; // invalid param
			if (messageType == null)
				return; // invalid param

			// now look up for link to registered messageType
			MLink tmp = linkOf(messageType);

			// check link and insert or create new type link
			if (tmp != null)
			{ // type is already known!

				if (tmp.clients.Contains(output))
				{ // check if already reg'd
					return; // already inside
				}
				else
				{ // client is new to this messagetype, so...
					tmp.clients.Add(output); // ...add the client
					return; // we're done
				}

			}
			else
			{ // messageType not registered here, so do it now
			  // create the new link. New Links are added at first position
				_head = new MLink(_head, messageType, true);
				_head.clients.Add(output); // add the output
			}

		}

