		/**
		 * Skips the transmission of the next tracenote or increases the skipCounter
		 * by one. This is necessary to blend out any activities managed by the
		 * framework that would otherwise confuse the modeller.
		 */
		public void skip(Type messageType) {

			if (messageType == null)
				return; // no good parameter

			MLink tmp = linkOf(messageType); // buffer the link to the msgType

			if (tmp == null)
				return; // type not registered, return

			tmp.skipCount++; // well, just increase by one :-)

		}

		/// <summary>
		/// Skips the transmission of a number of future messages by increasing the skipCount by the given number.
		/// This is necessary to blend out any activities managed by the framework that would otherwise confuse the
		/// modeller.
		/// </summary>
		/// <param name="skipNumber">The number of messages to skip</param>
		public void skip(Type messageType, int skipNumber) {

			if (skipNumber < 1)
				return; // check parameters for correctness

			if (messageType == null)
				return;

			MLink tmp = linkOf(messageType);

			if (tmp == null)
				return;

			tmp.skipCount += skipNumber; // increase by given number

		}

		/// <summary>Disables messages of the given type to be sent to the registered receivers.</summary>
		/// <param name="messageType">The type of messages to be switched off</param>
		public void switchOff(Type messageType) {

			if (messageType == null)
				return; // no good parameter

			MLink tmp = linkOf(messageType); // buffer the link to the msgType

			if (tmp == null)
				return; // type not registered, return

			tmp.isOn = false; // well, just stop sending

		}

		/// <summary>Enables messages of the given type to be sent to the registered receivers.</summary>
		/// <param name="messageType">The type of messages to be switched on</param>
		public void switchOn(Type messageType) {

			if (messageType == null)
				return; // no good parameter

			MLink tmp = linkOf(messageType); // buffer the link to the msgType

			if (tmp == null)
				return; // type not registered, return

			tmp.isOn = true; // well, go on and distribute

		}
	}
